          "type": "string"
        },
        "start_time": {
          "type": "string"
        },
        "end_time": {
          "type": "string"
        },
        "tjlx": {
          "default": "2",
          "type": "string"
        }
      },
      "required": [
        "org_name",
        "start_time",
        "end_time"
      ],
      "type": "object"
    }
  }
}

